#include <stdio.h>
#include <fcntl.h>
#include <dirent.h>

int main() {
    int fd = open(".", O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 1;
    }
    DIR *dir = fdopendir(fd);
    if (dir == NULL) {
        perror("fdopendir");
        return 1;
    }
    closedir(dir);
    return 0;
}
